using System.Globalization;using System.Text;using Essco.Application.Billing;using Essco.Application.Inventory;using Essco.Application.Payroll;using Essco.Application.Security;using Essco.Domain.Billing;using Essco.Domain.Payroll;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace Essco.Web.Pages.Reports;
[Authorize(Policy=Permissions.Reports)]public sealed class IndexModel(ElectronicInvoiceService billing,InventoryService inventory,PayrollService payroll):PageModel
{public void OnGet(){}public async Task<FileResult>OnGetInvoicesAsync(DateOnly?from,DateOnly?to,CancellationToken t){var rows=await billing.ListAsync(new ElectronicInvoiceFilter(From:from,To:to),t);return Csv("facturas.csv",["Documento","Clave","Consecutivo","Fecha","Cliente","Moneda","Subtotal","Impuesto","Total","Hacienda"],rows.Select(x=>new[]{x.DocumentNumber,x.Key,x.Consecutive,x.IssueDate.ToString("yyyy-MM-dd"),x.CustomerCode+" - "+x.CustomerName,x.Currency,N(x.Subtotal),N(x.Tax),N(x.Total),x.HaciendaStatus}));}public async Task<FileResult>OnGetInventoriesAsync(CancellationToken t){var rows=await inventory.ListAsync(t);return Csv("inventarios.csv",["Inventario","Fecha","Título","Cerrado","Inicial","Final","Entradas","Salidas","Diferencias"],rows.Select(x=>new[]{x.Id.ToString(),x.Date.ToString("yyyy-MM-dd"),x.Title,x.Closed?"Sí":"No",N(x.InitialValue),N(x.FinalValue),N(x.Entries),N(x.Exits),N(x.Differences)}));}public async Task<FileResult>OnGetPayrollAsync(DateOnly?from,DateOnly?to,CancellationToken t){var rows=await payroll.ListAsync(new PayrollFilter(from,to),t);return Csv("planillas.csv",["Planilla","Desde","Hasta","Creada","Comentario","Usuario","Estado"],rows.Select(x=>new[]{x.Number.ToString(),x.From.ToString("yyyy-MM-dd"),x.To.ToString("yyyy-MM-dd"),x.CreatedAt.ToString("O"),x.Comments,x.CreatedBy,x.Status.ToString()}));}private FileContentResult Csv(string name,IReadOnlyList<string>headers,IEnumerable<string[]>rows){var b=new StringBuilder();b.AppendLine(string.Join(',',headers.Select(Escape)));foreach(var row in rows)b.AppendLine(string.Join(',',row.Select(Escape)));return File(new UTF8Encoding(true).GetBytes(b.ToString()),"text/csv; charset=utf-8",name);}private static string Escape(string?x)=>$"\"{(x??"").Replace("\"","\"\"")}\"";private static string N(decimal x)=>x.ToString(CultureInfo.InvariantCulture);}
